'use strict';
/** Lazy access also catches opaque file/preview origins throwing on localStorage itself. */
function createStorage(getStorage) {
    return {
        get(key) {
            try {
                return JSON.parse(getStorage().getItem(key));
            }
            catch {
                return null;
            }
        },
        set(key, value) {
            try {
                getStorage().setItem(key, JSON.stringify(value));
                return true;
            }
            catch {
                return false;
            }
        }
    };
}
module.exports = createStorage;

